window.products.push({"id":1097024,"name":"Bathroom faucet aerator with Flow Control Valve - 1.0 GPM - Low Flow","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/11AgC+t2i8L.jpg","description":"This efficient bathroom faucet aerator uses only 1.0 gpm and achieves a high velocity spray. It allows to reduce the flow to a trickle while maintaining temperature control which is important while shaving and washing your hands and face. Save water, the energy used to heat water, and money spent on water and wastewater utility bills. All proceeds from the sales of this device are used in our programs to 'Conserve Water through Local Action'.","images":["https://m.media-amazon.com/images/I/11AgC+t2i8L.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"UnAssigned","source_asin":"B0032XZ5GQ","category_path":"Home & Kitchen"},"sku":"BM-1097024","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0032XZ5GQ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0032XZ5GQ","price_pending":true,"merchant_ready":false});
