window.products.push({"id":1097055,"name":"UFO/Alien Saucer Glass Christmas Ornament","category":"homeandappliances","retail price":21.13,"sale price":null,"image":"https://m.media-amazon.com/images/I/81CTL1KoinL._AC_SL1500_.jpg","description":"4.45 Inches x 4.06 Inches x 3.27 Inches Glass Hand Painted Mouth Blown Glittered Accents Gift Boxed Each of our ornaments is meticulously crafted by hand using traditional techniques that originated in the 1800s. The Renaissance-era carving, molding, glass blowing, silver lining, painting and finishing processes require unparalleled skill and several weeks to complete. The molten glass is mouth-blown into finely carved molds to shape the ornament. It is then painted and glittered in a series of labor-intensive steps to achieve the beautiful final products. Exquisite workmanship and details are the hallmarks of all BestPysanky ornaments. We aim to bring warmth, color, spirit and sparkle into your home with our unique decor, as you admire and celebrate the holidays with your loved ones. It's more than just an ornament- it's a work of art!","images":["https://m.media-amazon.com/images/I/81CTL1KoinL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"BestPysanky","source_asin":"B07H77M3S3","category_path":"Home & Kitchen"},"sku":"BM-1097055","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07H77M3S3","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07H77M3S3","price_pending":true,"merchant_ready":false});
